import { forwardRef } from "react";
import { LineChart as RechartsLineChart, ResponsiveContainer } from "recharts";
import { useTheme } from "@theme";
import { clsx } from "clsx";

import { ChartClasses, StyledChart } from "./chart.styles";
import { ChartContext } from "./hooks/use-chart";
import { useLineChart } from "./hooks/use-line-chart";
import { LineChartProps } from "./chart.types";

const LineChart = forwardRef<HTMLDivElement, LineChartProps>(
  (
    {
      data: initialData,
      children,
      className,
      style,
      styleSlots,
      variant = "default",
      showLineLabels,
      margin = { top: 10, right: 10, left: 10, bottom: 10 },
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const { chartData, numCategoricalColors, numLines, childrenWithProps } = useLineChart({
      data: initialData,
      children,
    });

    return (
      <ChartContext.Provider
        value={{
          data: initialData,
          chartData,
          numCategoricalColors,
          numLines,
          showLineLabels,
        }}
      >
        <StyledChart
          ref={ref}
          className={clsx(ChartClasses.root, className)}
          currentTheme={theme}
          style={{ width: "100%", height: "100%", ...style }}
          styleSlots={styleSlots}
          variant={variant}
          {...props}
        >
          <ResponsiveContainer
            className={ChartClasses.responsiveContainer}
            height="100%"
            width="100%"
          >
            <RechartsLineChart className={ChartClasses.lineChart} data={chartData} margin={margin}>
              {childrenWithProps}
            </RechartsLineChart>
          </ResponsiveContainer>
        </StyledChart>
      </ChartContext.Provider>
    );
  },
);

LineChart.displayName = "LineChart";

export default LineChart;
